        n = client.get_note(note_id)
        print(f'Note ID: {n.id}')
        print(f'Forum: {n.forum}')
        if isinstance(n.content, dict):
            for k in ['title', 'venue', 'venueid', 'authors']:
                v = n.content.get(k, {})
                if isinstance(v, dict):
                    print(f'{k}: {v.get("value","")}')
                else:
                    print(f'{k}: {v}')
        return n
    except Exception as e:
        print(f'Error: {e}')
        return None

# Get Lemur details
lemur = get_bibtex('hNhwSmtXRh')
print('---')

